<section class="page-head"><div><span class="eyebrow"><?=e(__('ui.mobility'))?></span><h1><?=e(__('transport.title'))?></h1><p><?=e(__('transport.subtitle'))?></p></div></section><div class="split-grid"><div class="panel"><form method="post" action="<?=e(url('/transport/request'))?>" class="form-stack"><?=csrf_field()?><label><?=e(__('transport.pickup'))?><input name="pickup" required></label><label><?=e(__('transport.destination'))?><input name="destination" required></label><label><?=e(__('transport.vehicle'))?><select name="vehicle_type" required><?php foreach($types as $type):?><option value="<?=e($type['id'])?>"><?=e($type['slug'])?> · <?=e(money($type['base_fare']))?> + km</option><?php endforeach;?></select></label><button class="btn primary big" type="submit"><?=e(__('transport.request'))?></button></form></div><div class="panel dark-panel"><span class="eyebrow"><?=e(__('ui.fare_model'))?></span><h2><?=e(__('transport.estimate'))?></h2><p>Estimate = base fare + distance component + duration component. The request stores a fare snapshot for auditability.</p><div class="fare-list"><?php foreach($types as $type):?><div><strong><?=e($type['slug'])?></strong><span><?=e(money($type['base_fare']))?></span></div><?php endforeach;?></div></div></div>
